CREATE TABLE whats_new_posts (
  post_id TEXT PRIMARY KEY,
  revision INTEGER NOT NULL CHECK (revision > 0),
  date TEXT NOT NULL,
  title TEXT NOT NULL,
  paragraphs_json TEXT NOT NULL CHECK (json_valid(paragraphs_json)),
  status TEXT NOT NULL CHECK (status IN ('draft', 'published')),
  publication_sequence INTEGER UNIQUE CHECK (publication_sequence > 0),
  source_from TEXT,
  source_through TEXT,
  updated_at TEXT NOT NULL,
  CHECK (status <> 'published' OR publication_sequence IS NOT NULL)
);
CREATE TABLE whats_new_post_revisions (
  post_id TEXT NOT NULL REFERENCES whats_new_posts(post_id),
  revision INTEGER NOT NULL CHECK (revision > 0),
  actor_id TEXT NOT NULL,
  saved_at TEXT NOT NULL,
  post_json TEXT NOT NULL CHECK (json_valid(post_json)),
  PRIMARY KEY (post_id, revision)
);
CREATE TRIGGER whats_new_post_revisions_immutable_update
BEFORE UPDATE ON whats_new_post_revisions BEGIN
  SELECT RAISE(ABORT, 'Blog revisions are immutable');
END;
CREATE TRIGGER whats_new_post_revisions_immutable_delete
BEFORE DELETE ON whats_new_post_revisions BEGIN
  SELECT RAISE(ABORT, 'Blog revisions are immutable');
END;
INSERT INTO whats_new_posts VALUES ('update-2026-09-09', 1, '2026-09-09', 'Give a dismissed suggestion another look', '["Dismissed a reflection proposal by mistake? Open By session in Reflections and use Undo dismiss to return it to Help."]', 'published', 1, NULL, NULL, '2026-09-09T00:00:00.000Z');
