INSERT INTO whats_new_posts VALUES ('update-2026-09-11', 1, '2026-09-11', 'Study just the words in your stash', '["Session settings now let you choose stash-only new words. The default still mixes your stash with the app’s selection. Choose stash-only when you want to concentrate on vocabulary you’ve picked yourself."]', 'published', 2, NULL, NULL, '2026-09-11T00:00:00.000Z');
INSERT INTO whats_new_post_revisions VALUES ('update-2026-09-11', 1, 'migration:0028', '2026-09-11T00:00:00.000Z', '{"id": "update-2026-09-11", "revision": 1, "date": "2026-09-11", "title": "Study just the words in your stash", "paragraphs": ["Session settings now let you choose stash-only new words. The default still mixes your stash with the app’s selection. Choose stash-only when you want to concentrate on vocabulary you’ve picked yourself."], "status": "published", "publicationSequence": 2, "sourceFrom": null, "sourceThrough": null, "updatedAt": "2026-09-11T00:00:00.000Z"}');
INSERT INTO whats_new_posts VALUES ('update-2026-09-13', 1, '2026-09-13', 'Find your words and your starting point', '["Words → My words gives you a place to browse your collection and inspect individual words, including recent additions and words with personal notes.", "Before your first session, you can answer a few questions to help choose a starting level or pick it yourself. After a session, you can nudge the suggested vocabulary easier or harder."]', 'published', 3, NULL, NULL, '2026-09-13T00:00:00.000Z');
