INSERT INTO whats_new_posts VALUES ('update-2026-09-14', 1, '2026-09-14', 'A home for help and updates', '["About now brings getting-started advice, a usage guide, known limitations, and these update notes into the left rail. We’ll keep adding entries here as the app evolves."]', 'published', 4, NULL, NULL, '2026-09-14T00:00:00.000Z');
