INSERT INTO whats_new_posts VALUES ('update-2026-09-16', 1, '2026-09-16', 'Filter My words by stage or recent lapses', '["Words → My words now has chips to show only Not yet studied, Learning, or In review words. Turn on Recent lapses when you want to look at words you recently forgot or whose last learning attempt didn’t go well. The chips work with search across Recently studied, Personally added, and Current deck."]', 'published', 5, NULL, NULL, '2026-09-16T00:00:00.000Z');
INSERT INTO whats_new_post_revisions VALUES ('update-2026-09-16', 1, 'migration:0028', '2026-09-16T00:00:00.000Z', '{"id": "update-2026-09-16", "revision": 1, "date": "2026-09-16", "title": "Filter My words by stage or recent lapses", "paragraphs": ["Words → My words now has chips to show only Not yet studied, Learning, or In review words. Turn on Recent lapses when you want to look at words you recently forgot or whose last learning attempt didn’t go well. The chips work with search across Recently studied, Personally added, and Current deck."], "status": "published", "publicationSequence": 5, "sourceFrom": null, "sourceThrough": null, "updatedAt": "2026-09-16T00:00:00.000Z"}');
INSERT INTO whats_new_posts VALUES ('update-2026-09-17', 1, '2026-09-17', 'See what’s waiting, finish with Space, and pick the right stash word', '["Reflections and About can now show a little number when something’s waiting. Reflections counts new Help cards after a session. About counts unread What’s New notes, including this one. Open the page and the count goes away.", "When you hit the session summary, Space now finishes the session the same way Finish session does. Heading somewhere else in the app also wraps it up, so the last attempt is saved and a reflection can start without you sitting on the waiting screen. Leaving in the middle of a session is unchanged, and closing the tab still isn’t a reliable way to finish.", "Stash add got two small improvements. You no longer have to type the comma in a saying: 吃一堑长一智 still finds 吃一堑，长一智. And if what you typed matches more than one unstudied word, a picker pops up so you can choose which ones to add instead of getting all of them. One match still adds immediately."]', 'published', 6, NULL, NULL, '2026-09-17T00:00:00.000Z');
INSERT INTO whats_new_post_revisions VALUES ('update-2026-09-17', 1, 'migration:0028', '2026-09-17T00:00:00.000Z', '{"id": "update-2026-09-17", "revision": 1, "date": "2026-09-17", "title": "See what’s waiting, finish with Space, and pick the right stash word", "paragraphs": ["Reflections and About can now show a little number when something’s waiting. Reflections counts new Help cards after a session. About counts unread What’s New notes, including this one. Open the page and the count goes away.", "When you hit the session summary, Space now finishes the session the same way Finish session does. Heading somewhere else in the app also wraps it up, so the last attempt is saved and a reflection can start without you sitting on the waiting screen. Leaving in the middle of a session is unchanged, and closing the tab still isn’t a reliable way to finish.", "Stash add got two small improvements. You no longer have to type the comma in a saying: 吃一堑长一智 still finds 吃一堑，长一智. And if what you typed matches more than one unstudied word, a picker pops up so you can choose which ones to add instead of getting all of them. One match still adds immediately."], "status": "published", "publicationSequence": 6, "sourceFrom": null, "sourceThrough": null, "updatedAt": "2026-09-17T00:00:00.000Z"}');
INSERT INTO whats_new_posts VALUES ('update-2026-09-22', 1, '2026-09-22', 'A smoother ride when more than one answer is right', '["Some prompts really do have more than one good Chinese answer. We’re making that feel less like a gotcha. If you type something that fits the cue, we want the app to treat it as a success more often, instead of acting as if you’d missed one hidden target word.", "You may see this in a few places. After you reveal a production cue, the card can list every accepted answer, not just one. Some of that practice now follows the prompt itself rather than a single word, so a card labeled Pure cue production can show up alongside ordinary word reviews. And if a reflection decides your “Forgot” was actually a valid alternative, it can offer to treat the cue as shared. Authorize that and it can also unwind the unfair miss so the original word isn’t punished.", "This is new, so expect a few bumps. A suggestion might be too broad, a card might show up at an odd time, or the reveal might list more answers than you expected. Read those proposals before applying them. If something feels off, send the cue, what you typed, and what you expected to the person who invited you.", "A few smaller changes. Fixed a bug in My Words which led to the Recent Lapses selector picking up today’s newly learned words. Reflections shows a spinner on the tab while a reflection is generating, including after you close the session summary, hides its count while you’re already there, and uses a red ! if generation failed — open Run meta to clear that."]', 'published', 7, NULL, NULL, '2026-09-22T00:00:00.000Z');
INSERT INTO whats_new_post_revisions VALUES ('update-2026-09-22', 1, 'migration:0028', '2026-09-22T00:00:00.000Z', '{"id": "update-2026-09-22", "revision": 1, "date": "2026-09-22", "title": "A smoother ride when more than one answer is right", "paragraphs": ["Some prompts really do have more than one good Chinese answer. We’re making that feel less like a gotcha. If you type something that fits the cue, we want the app to treat it as a success more often, instead of acting as if you’d missed one hidden target word.", "You may see this in a few places. After you reveal a production cue, the card can list every accepted answer, not just one. Some of that practice now follows the prompt itself rather than a single word, so a card labeled Pure cue production can show up alongside ordinary word reviews. And if a reflection decides your “Forgot” was actually a valid alternative, it can offer to treat the cue as shared. Authorize that and it can also unwind the unfair miss so the original word isn’t punished.", "This is new, so expect a few bumps. A suggestion might be too broad, a card might show up at an odd time, or the reveal might list more answers than you expected. Read those proposals before applying them. If something feels off, send the cue, what you typed, and what you expected to the person who invited you.", "A few smaller changes. Fixed a bug in My Words which led to the Recent Lapses selector picking up today’s newly learned words. Reflections shows a spinner on the tab while a reflection is generating, including after you close the session summary, hides its count while you’re already there, and uses a red ! if generation failed — open Run meta to clear that."], "status": "published", "publicationSequence": 7, "sourceFrom": null, "sourceThrough": null, "updatedAt": "2026-09-22T00:00:00.000Z"}');
INSERT INTO whats_new_posts VALUES ('update-2026-09-23', 1, '2026-09-23', 'Choose simplified, traditional, or both on study cards', '["Study cards can now follow the characters you want to practice. Open the gear beside Start session and set Card characters to Simplified, Traditional, or Both. Simplified stays the default. Both shows the two forms together when they differ, like 门 / 門.", "Card characters controls word headings, recognition prompts, answers, and contrast choices. Sentences and examples follow that choice. If you choose Both, a second option lets you read sentences and examples in Simplified or Traditional. A revealed cloze uses one answer form matching its sentence; a separate answer can still show both. Personal notes stay as you wrote them.", "Typing works the same in every setting. A production answer still counts if you type the simplified form or the traditional one."]', 'published', 8, NULL, NULL, '2026-09-23T00:00:00.000Z');
INSERT INTO whats_new_post_revisions VALUES ('update-2026-09-23', 1, 'migration:0028', '2026-09-23T00:00:00.000Z', '{"id": "update-2026-09-23", "revision": 1, "date": "2026-09-23", "title": "Choose simplified, traditional, or both on study cards", "paragraphs": ["Study cards can now follow the characters you want to practice. Open the gear beside Start session and set Card characters to Simplified, Traditional, or Both. Simplified stays the default. Both shows the two forms together when they differ, like 门 / 門.", "Card characters controls word headings, recognition prompts, answers, and contrast choices. Sentences and examples follow that choice. If you choose Both, a second option lets you read sentences and examples in Simplified or Traditional. A revealed cloze uses one answer form matching its sentence; a separate answer can still show both. Personal notes stay as you wrote them.", "Typing works the same in every setting. A production answer still counts if you type the simplified form or the traditional one."], "status": "published", "publicationSequence": 8, "sourceFrom": null, "sourceThrough": null, "updatedAt": "2026-09-23T00:00:00.000Z"}');
INSERT INTO whats_new_posts VALUES ('update-2026-09-27', 1, '2026-09-27', 'Reflection proposals for vague production prompts', '["We’ve made some changes to how reflection generates content improvement proposals, especially when a production mistake comes from a vague prompt.", "If a proposal looks questionable, or anything else behaves oddly, please capture it and share it with Justin."]', 'published', 9, NULL, NULL, '2026-09-27T00:00:00.000Z');
INSERT INTO whats_new_post_revisions VALUES ('update-2026-09-27', 1, 'migration:0028', '2026-09-27T00:00:00.000Z', '{"id": "update-2026-09-27", "revision": 1, "date": "2026-09-27", "title": "Reflection proposals for vague production prompts", "paragraphs": ["We’ve made some changes to how reflection generates content improvement proposals, especially when a production mistake comes from a vague prompt.", "If a proposal looks questionable, or anything else behaves oddly, please capture it and share it with Justin."], "status": "published", "publicationSequence": 9, "sourceFrom": null, "sourceThrough": null, "updatedAt": "2026-09-27T00:00:00.000Z"}');
INSERT INTO whats_new_posts VALUES ('update-2026-10-02', 1, '2026-10-02', 'New words start with a short walkthrough', '["A new word no longer opens as one card with the characters, pronunciation, and a single example. You read a short introduction one beat at a time. Space or Next beat shows the next thought, and earlier beats stay on the page. Finish walkthrough at the end. There is no skip straight to the drills.", "Reading it does not count as learning the word. Continue, and the session mixes in the usual practice: recognize the word, and type the expression the introduction taught. That prompt wants the taught expression, so another natural answer may not count. When you reveal an answer, you may see the uses and examples from the introduction.", "If an introduction is not ready, that new word waits instead of using the old card. Start session may wait up to about 30 seconds while material is prepared, or ask you to check again later, and you may get fewer new words than your daily limit. Words you are already learning keep their existing cards. The daily new-word limit now stops at 20."]', 'published', 10, NULL, NULL, '2026-10-02T00:00:00.000Z');
INSERT INTO whats_new_post_revisions VALUES ('update-2026-10-02', 1, 'migration:0028', '2026-10-02T00:00:00.000Z', '{"id": "update-2026-10-02", "revision": 1, "date": "2026-10-02", "title": "New words start with a short walkthrough", "paragraphs": ["A new word no longer opens as one card with the characters, pronunciation, and a single example. You read a short introduction one beat at a time. Space or Next beat shows the next thought, and earlier beats stay on the page. Finish walkthrough at the end. There is no skip straight to the drills.", "Reading it does not count as learning the word. Continue, and the session mixes in the usual practice: recognize the word, and type the expression the introduction taught. That prompt wants the taught expression, so another natural answer may not count. When you reveal an answer, you may see the uses and examples from the introduction.", "If an introduction is not ready, that new word waits instead of using the old card. Start session may wait up to about 30 seconds while material is prepared, or ask you to check again later, and you may get fewer new words than your daily limit. Words you are already learning keep their existing cards. The daily new-word limit now stops at 20."], "status": "published", "publicationSequence": 10, "sourceFrom": null, "sourceThrough": null, "updatedAt": "2026-10-02T00:00:00.000Z"}');
INSERT INTO whats_new_posts VALUES ('update-2026-10-05', 1, '2026-10-05', 'A quieter study desk, and a fairer failure rate', '["The app has a warmer, quieter palette: paper in the background, green for the ink and buttons. In a session, one card stays in the center, with the prompt, your answer, and the buttons together. The next card waits just behind it. A finished card moves off; a miss settles into Practice again at the bottom. On a fill-in-the-blank, the answer appears in the blank when you reveal it.", "New-word introductions now keep the current beat in one reading place, with earlier beats still on the page above it. If you scroll back, Space returns you there before it advances. We are still tuning this walkthrough, so expect that part of a session to keep changing.", "Sometimes a miss is the prompt’s fault: the cue was vague, or another answer was also fair. If you accept a reflection proposal that says so, that miss is compensated. The app puts the review back roughly where it was, so you are not punished for a bad prompt. The attempt itself stays in your history. On Home, Exercise failure rate now shows Adjusted failure and Compensation. Adjusted failure is your misses after those unfair ones are taken back, so the number can fall when a compensation is applied, even for an earlier miss. Compensation is how often that has happened. Open Rate details if you want the raw counts."]', 'published', 11, NULL, NULL, '2026-10-05T00:00:00.000Z');
INSERT INTO whats_new_post_revisions VALUES ('update-2026-10-05', 1, 'migration:0028', '2026-10-05T00:00:00.000Z', '{"id": "update-2026-10-05", "revision": 1, "date": "2026-10-05", "title": "A quieter study desk, and a fairer failure rate", "paragraphs": ["The app has a warmer, quieter palette: paper in the background, green for the ink and buttons. In a session, one card stays in the center, with the prompt, your answer, and the buttons together. The next card waits just behind it. A finished card moves off; a miss settles into Practice again at the bottom. On a fill-in-the-blank, the answer appears in the blank when you reveal it.", "New-word introductions now keep the current beat in one reading place, with earlier beats still on the page above it. If you scroll back, Space returns you there before it advances. We are still tuning this walkthrough, so expect that part of a session to keep changing.", "Sometimes a miss is the prompt’s fault: the cue was vague, or another answer was also fair. If you accept a reflection proposal that says so, that miss is compensated. The app puts the review back roughly where it was, so you are not punished for a bad prompt. The attempt itself stays in your history. On Home, Exercise failure rate now shows Adjusted failure and Compensation. Adjusted failure is your misses after those unfair ones are taken back, so the number can fall when a compensation is applied, even for an earlier miss. Compensation is how often that has happened. Open Rate details if you want the raw counts."], "status": "published", "publicationSequence": 11, "sourceFrom": null, "sourceThrough": null, "updatedAt": "2026-10-05T00:00:00.000Z"}');
INSERT INTO whats_new_posts VALUES ('update-2026-10-06', 1, '2026-10-06', 'Connect the words you studied to your interests', '["The words you study can take you somewhere unexpected. After a session, Connections brings a few of them to life with short notes: a surprising turn of phrase, a glimpse of Chinese culture, or a link to something you love. Look for them in your session summary. They can take a little time to arrive, so feel free to head back to Home and reopen your latest session later.", "Give Connections a few starting points: open the gear beside Start session, add topics under Interests, and save. Tennis, historical dramas, video games, cooking—whatever has your curiosity. Future sessions can draw on those interests, and you can leave the field blank to let the words lead the way.", "The summary may also show Coming back more reliably, when words that were repeatedly tricky have started to stick. It’s a highlight, not a change to when the word comes due.", "Missed a review and don’t want the extra practice that follows? Skip reinforcement finishes that item for the session. The miss still counts in the moment, and compensation is determined on a slightly slower cadence.", "Card characters still offers Simplified, Traditional, or Both. This will now apply to not just the exercise word(s) but also any Mandarin content associated with it (like an example sentence). When Both is set, the additional Sentences and examples setting lets you pick which character system the study content should use."]', 'published', 12, NULL, NULL, '2026-10-06T00:00:00.000Z');
